const social = {
  id:'social',
  copy:{
    title: 'Social',
    copy: <>Keeping it safe and simple is our guiding principle whenever we approach any lift. Be it the first time or the thousandth we ensure it is the safest and most efficient way to complete the lift.<br/><br/>We encourage our crane crew to talk to clients about what it is there lifting, what it does and where it's going to ensure they are best equipped to tackle the task ahead.</>
  }
};

const Social = () => (
  <section className='container-fluid p-0 min-vh-100 parallax' id={social.id}>
    <div className='container-fluid p-0 min-vh-100 d-flex justify-content-center align-items-center'>
      <div className='row px-4 g-0 justify-content-center align-items-center '>
        <div className='col-md-4 offset-md-2 text-white'>
        <h2>{social.copy.title}</h2>
          {social.copy.copy}
        </div>
      </div>
    </div>
  </section >
)

export default Social;
